/* ---------------- storage ---------------- */
export const KEY = 'ironlog.v1';


/* Persistence runs through IndexedDB — it's async (so the call sites below don't
   change) and Chrome gives it a far bigger quota than localStorage.
   localStorage is kept as a fallback for the rare build where IndexedDB is
   unavailable. Neither survives the app's data being cleared: the copies that
   do are Drive sync (below, and sync.js) and a JSON export from ⚙. */
let STORAGE_OK = true;
let warnedStorage = false;

const DB_NAME = 'ironlog', DB_STORE = 'kv';
let dbPromise = null;

function openDB() {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((res, rej) => {
    if (!self.indexedDB) return rej(new Error('no indexedDB'));
    const req = indexedDB.open(DB_NAME, 1);
    req.onupgradeneeded = () => {
      if (!req.result.objectStoreNames.contains(DB_STORE)) req.result.createObjectStore(DB_STORE);
    };
    req.onsuccess = () => res(req.result);
    req.onerror = () => rej(req.error);
    req.onblocked = () => rej(new Error('blocked'));
  });
  // a failed open is not kept: the next read or write asks storage again (B-227)
  dbPromise.catch(() => { dbPromise = null; });
  return dbPromise;
}

export function idb(mode, fn) {
  return openDB().then(db => new Promise((res, rej) => {
    const tx = db.transaction(DB_STORE, mode);
    const r = fn(tx.objectStore(DB_STORE));
    /* A write only counts once the transaction commits (B-036): a put can
       succeed and the commit still abort (quota, the tab killed). */
    if (mode === 'readwrite') tx.oncomplete = () => res(r.result);
    else r.onsuccess = () => res(r.result);
    r.onerror = () => rej(r.error);
    tx.onabort = () => rej(tx.error || new Error('aborted'));
  }));
}

/* A read that fails is not the same as nothing stored: opening as a fresh
   install, the next save could land on top of the real log once IndexedDB
   answered again. So a failed
   read with no fallback copy throws when `strict` (the log itself, at boot),
   and boot shows the rescue screen. Skins, photos and clips keep the old
   answer of "nothing there". A browser with no IndexedDB at all still runs
   on localStorage as before. */
/* A localStorage copy is only written when IndexedDB failed, and is cleared
   by the next IndexedDB write that lands (B-035). So a copy marked as a
   fallback is newer than whatever IndexedDB holds, and wins at read. */
const fallbackMark = k => `${k}.fallback`;
/* "Start with an empty log" while IndexedDB didn't answer (B-227): the real
   log may still be in there, unread. The rescue screen sets this mark, and
   the first write that reaches IndexedDB moves what it holds to a rescue key
   of its own before anything goes over it. */
export const emptyStartMark = k => `${k}.emptyStart`;
/* Copies of the whole log set aside on this phone: by the rescue screen, by
   a migration before it runs, by a restore before it replaces the log. Each
   gets its own timestamped key, so a second rescue or a migration run again
   never writes over an earlier copy (B-234). Keys written before 0.100.4 had
   no time (`.rescue`, `.before-<id>`) and are still read: parseAsideKey. */
export function setAsideKey(kind, id) {
  const t = Date.now();
  return kind === 'before' ? `${KEY}.before-${id}@${t}` : kind === 'rescue' ? `${KEY}.rescue-${t}` : `${KEY}.aside-${t}`;
}
export function parseAsideKey(k) {
  if (typeof k !== 'string' || !k.startsWith(KEY + '.')) return null;
  const rest = k.slice(KEY.length + 1);
  let m = /^rescue(?:-(\d+))?$/.exec(rest);
  if (m) return { key: k, kind: 'rescue', t: m[1] ? +m[1] : null };
  m = /^aside-(\d+)$/.exec(rest);
  if (m) return { key: k, kind: 'aside', t: +m[1] };
  m = /^before-(.+?)(?:@(\d+))?$/.exec(rest);
  if (m) return { key: k, kind: 'before', migration: m[1], t: m[2] ? +m[2] : null };
  return null;
}
export async function setAsideIfStartedEmpty(k) {
  let t = null;
  try { t = localStorage.getItem(emptyStartMark(k)); } catch (e) { /* blocked */ }
  if (!t) return;
  const cur = await idb('readonly', st => st.get(k));   // throws while storage is still down: nothing written
  if (cur != null) await idb('readwrite', st => st.put(cur, `${k}.rescue-${t}`));
  try { localStorage.removeItem(emptyStartMark(k)); } catch (e) { /* blocked */ }
}
export async function storeGet(k, strict) {
  try {
    if (localStorage.getItem(fallbackMark(k))) {
      const ls = localStorage.getItem(k);
      if (ls != null) return ls;
    }
  } catch (e) { /* blocked: fall through to IndexedDB */ }
  let failed = null;
  try {
    const v = await idb('readonly', st => st.get(k));
    if (v != null) return v;          // undefined = fresh install, not an error
  } catch (e) { failed = e; }
  let ls = null;
  try { ls = localStorage.getItem(k); } catch (e) { /* blocked: same as empty */ }
  if (strict && ls == null && failed && self.indexedDB) throw new Error(`This phone's storage didn't answer (${failed.message || failed.name || 'read failed'})`);
  return ls;
}

export async function storePut(k, v) {
  let ok = false;
  try {
    await setAsideIfStartedEmpty(k);
    await idb('readwrite', st => st.put(v, k)); ok = true;
    try { if (localStorage.getItem(fallbackMark(k))) { localStorage.removeItem(k); localStorage.removeItem(fallbackMark(k)); } }
    catch (e) { /* blocked: nothing to clear */ }
  } catch (e) {
    try { localStorage.setItem(k, v); localStorage.setItem(fallbackMark(k), String(Date.now())); ok = true; }   // only mirror when IDB is down
    catch (e2) { ok = false; }
  }
  STORAGE_OK = ok;
  if (ok) warnedStorage = false;   // once per failure, not once per app load: it warns again after a recovery (B-118)
  if (!ok && !warnedStorage) {
    warnedStorage = true;
    toast('⚠ Storage is not responding — your log may not survive a refresh. Export from ⚙ to keep it.');
  }
  return ok;
}

/* Ask Android not to evict the log when storage runs low. Granted automatically
   once the app is installed to the home screen. */
/* ---------------- storage safety (roadmap A3) ----------------
   Chrome may clear an origin's IndexedDB when the phone runs short of space —
   unless the origin is "persisted". Chrome decides on its own (an installed,
   used app usually qualifies), so ask once there is a logged session worth
   protecting, and show the answer in Settings. The backup nudge on Home is
   `backupDue` below: sooner when Drive sync is on, two weeks without it. */
export const persist = { state: 'unknown', usage: 0, quota: 0 };   // granted | denied | unsupported | unknown
export async function storageStatus() {
  try {
    if (!(navigator.storage && navigator.storage.persisted)) { persist.state = 'unsupported'; return persist; }
    persist.state = (await navigator.storage.persisted()) ? 'granted' : 'denied';
    if (navigator.storage.estimate) {
      const e = await navigator.storage.estimate();
      persist.usage = e.usage || 0; persist.quota = e.quota || 0;
    }
  } catch (e) { persist.state = 'unsupported'; }
  return persist;
}
export async function requestPersistence(force) {
  try {
    if (!(navigator.storage && navigator.storage.persist)) { persist.state = 'unsupported'; return persist.state; }
    if (await navigator.storage.persisted()) { persist.state = 'granted'; return persist.state; }
    // nothing worth protecting yet: don't spend the ask
    if (!force && !S.workouts.some(w => w.status === 'completed')) return persist.state;
    persist.state = (await navigator.storage.persist()) ? 'granted' : 'denied';
    S.settings.persistAskedAt = Date.now(); save();
  } catch (e) { persist.state = 'unsupported'; }
  return persist.state;
}
export const BACKUP_EVERY = 14 * 864e5, BACKUP_SNOOZE = 7 * 864e5;
/* When the last backup was, or null. A log with no backup at all counts from
   its first completed session, so a new user isn't nagged on day one. */
function backupDue() {
  const done = S.workouts.filter(w => w.status === 'completed');
  if (!done.length) return null;
  const now = Date.now(), st = S.settings;
  if (st.backupSnoozeUntil && now < st.backupSnoozeUntil) return null;
  const first = Math.min(...done.map(w => parseISO(w.date).getTime()));
  // a Drive sync is a backup too (B6)
  const last = Math.max(st.lastExportAt || 0, syncMeta().lastSyncAt || 0) || null;
  const since = last || first;
  /* Connected to Drive, backing up is one tap — so the reminder comes after 3 days, not 14. */
  return now - since > (syncMeta().connected ? 3 * 864e5 : BACKUP_EVERY) ? { last, days: Math.floor((now - since) / 864e5), drive: !!syncMeta().connected } : null;
}
/* ---------------- Home as the landing page (D14, r&d/specs/home-landing-spec.md)
   Someone who hasn't installed Ironlog, or hasn't logged a session yet, sees
   what it is first. Chrome's install offer is caught and kept for a button
   instead of the mini-infobar. */
export let installEvt = null;
export function setInstallEvt(v) { return installEvt = v; }   // installEvt is assigned from another module; an import is read-only
window.addEventListener('beforeinstallprompt', ev => { ev.preventDefault(); installEvt = ev; if (page === 'home' && !modalStack.length) render(); });
window.addEventListener('appinstalled', () => { installEvt = null; if (page === 'home') render(); });
